static int 
dtb_label_prop_dialog_create(
    DtbLabelPropDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    Arg	args[8];	/* need 3 args (add 5 to be safe) */
    int	n = 0;
    String	title_str = NULL;
    static DtbObjectHelpDataRec	help_data = {
        "",
        "AppBuilder",
        "ABPropsEditor",
    };
    char *tmp_txt;
    
    if (instance->prop_dialog == NULL) {
        title_str = XtNewString(CATGETS(Dtb_project_catd, 19, 1, "Label Property Editor"));
        n = 0;
        XtSetArg(args[n], XmNallowShellResize, True);  ++n;
        XtSetArg(args[n], XmNtitle, title_str);  ++n;
        XtSetArg(args[n], XmNbackground, dtb_cvt_string_to_pixel(parent, "white"));  ++n;
        instance->prop_dialog =
            XmCreateDialogShell(parent,
                "dtb_label_prop_dialog", args, n);
        XtFree(title_str);
        title_str = NULL;
    }
    if (instance->prop_dialog == NULL)
        return -1;

    if (instance->prop_dialog_shellform == NULL) {
        instance->prop_dialog_shellform =
            XtVaCreateWidget("dtb_label_prop_dialog_shellform",
                xmFormWidgetClass,
                instance->prop_dialog,
                XmNdefaultPosition, False,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog, "white"),
                NULL);
        /*
         * Add help callback
         */
        tmp_txt = CATGETS(Dtb_project_catd, 19, 40, "This Property Editor allows Label object attributes to be examined or altered.\n");
        help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
        strcpy(help_data.help_text,tmp_txt);
        
        XtAddCallback(instance->prop_dialog_shellform,
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    if (instance->prop_dialog_shellform == NULL)
        return -1;

    if (instance->prop_dialog_panedwin == NULL) {
        instance->prop_dialog_panedwin =
            XtVaCreateWidget("prop_dialog_panedwin",
                xmPanedWindowWidgetClass,
                instance->prop_dialog_shellform,
                XmNbottomOffset, 0,
                XmNbottomPosition, 100,
                XmNbottomAttachment, XmATTACH_POSITION,
                XmNrightOffset, 0,
                XmNrightPosition, 100,
                XmNrightAttachment, XmATTACH_POSITION,
                XmNleftOffset, 0,
                XmNleftPosition, 0,
                XmNleftAttachment, XmATTACH_POSITION,
                XmNtopOffset, 0,
                XmNtopPosition, 0,
                XmNtopAttachment, XmATTACH_POSITION,
                XmNsashWidth, 1,
                XmNsashHeight, 1,
                XmNspacing, 0,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog_shellform, "white"),
                NULL);
    }
    if (instance->prop_dialog_panedwin == NULL)
        return -1;

    if (instance->prop_dialog_form == NULL) {
        instance->prop_dialog_form =
            XtVaCreateWidget("prop_dialog_form",
                xmFormWidgetClass,
                instance->prop_dialog_panedwin,
                XmNallowResize, True,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_ANY,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog_panedwin, "white"),
                NULL);
    }
    if (instance->prop_dialog_form == NULL)
        return -1;

    return 0;
}



